-- M6 additive cumulative authored target. OFF/ON use the same protected schema.
-- Completes the transaction begun by the M6 delta; does not activate beta.
create function dv_collect_private.tcg_magic_on_demand_schema_v1() returns jsonb
 language plpgsql stable security definer set search_path=pg_catalog,public,dv_collect_private as $inventory$
 declare s jsonb;l jsonb;begin with checks as (
 select 'relation' k,n.nspname||'.'||c.relname name,jsonb_build_object('kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'options',c.reloptions,
 'rights',(select jsonb_agg(jsonb_build_array(r,v,case when c.relkind='S' then has_sequence_privilege(r,c.oid,v) else has_table_privilege(r,c.oid,v) end) order by r,v)
 from unnest(array['anon','authenticated','service_role']) r cross join lateral unnest(case when c.relkind='S' then array['USAGE','SELECT','UPDATE'] else array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'] end) v),
 'columns',(select jsonb_agg(jsonb_build_array(r,a.attname,v,has_column_privilege(r,c.oid,a.attnum,v)) order by r,a.attnum,v) from pg_attribute a cross join unnest(array['anon','authenticated','service_role']) r cross join unnest(array['SELECT','INSERT','UPDATE','REFERENCES']) v where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped and c.relkind<>'S'),
 'policies',(select jsonb_agg(jsonb_build_array(p.polname,p.polcmd,p.polpermissive,p.polroles::regrole[]::text[],pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname) from pg_policy p where p.polrelid=c.oid)) v
 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','dv_market_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private','dv_collect_private') and c.relkind in ('r','p','v','m','f','S')
 union all select 'function',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('body',md5(p.prosrc),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'result',pg_get_function_result(p.oid),'language',l.lanname,'volatility',p.provolatile,'strict',p.proisstrict,'rights',(select jsonb_agg(jsonb_build_array(r,has_function_privilege(r,p.oid,'EXECUTE')) order by r) from unnest(array['anon','authenticated','service_role']) r))
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','dv_market_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private','dv_collect_private') and p.proname not in ('get_security_schema_readiness_v1','get_market_legal_schema_readiness_v1')
 union all select 'schema',n.nspname,jsonb_agg(jsonb_build_array(r,has_schema_privilege(r,n.oid,'USAGE'),has_schema_privilege(r,n.oid,'CREATE')) order by r) from pg_namespace n cross join unnest(array['anon','authenticated','service_role']) r where n.nspname in ('public','dv_market_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private','dv_collect_private') group by n.oid,n.nspname
 union all select 'defaults',coalesce(n.nspname,'GLOBAL')||'.'||pg_get_userbyid(d.defaclrole)||'.'||d.defaclobjtype::text,jsonb_agg(jsonb_build_array(coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) order by coalesce(r.rolname,'PUBLIC'),a.privilege_type)
 from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) a left join pg_roles r on r.oid=a.grantee where d.defaclrole='postgres'::regrole and (n.nspname in ('public','dv_market_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private','dv_collect_private') or n.oid is null) group by n.nspname,d.defaclrole,d.defaclobjtype

 union all select 'trigger',n.nspname||'.'||c.relname||'.'||t.tgname,
 jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)
 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace
 where (n.nspname='dv_market_private' and (c.relname in ('battle_safety_causes','battle_safety_releases') or c.relname like 'c_%') or n.nspname='public') and (t.tgname in ('b1_immutable','c_immutable') or c.relname='battle_signals' or (c.relname='profiles' and t.tgname in ('battle_spectator_epoch_processing_hold','d4_protect_public_profile','b1_safety_projection','c_invalidate_marker_owner','guard_profile_username_direct_update')) or (c.relname in ('collection_items','collection_folders') and t.tgname='d4_protect_collection_publication')) and not t.tgisinternal

 union all select 'trigger',n.nspname||'.'||c.relname||'.'||t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)
 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace
 where not t.tgisinternal and t.tgname in ('tcg_validate_link','tcg_clear_stale_link')
 union all select 'seed','dv_collect_private.tcg_games',coalesce(jsonb_agg(to_jsonb(g) order by game_key collate "C"),'[]'::jsonb) from dv_collect_private.tcg_games g
 union all select 'seed','dv_collect_private.tcg_providers',coalesce(jsonb_agg(to_jsonb(g) order by provider_key collate "C"),'[]'::jsonb) from dv_collect_private.tcg_providers g
 union all select 'seed','dv_collect_private.tcg_provider_bindings',coalesce(jsonb_agg(to_jsonb(g) order by game_key collate "C",provider_key collate "C",provider_version collate "C"),'[]'::jsonb) from dv_collect_private.tcg_provider_bindings g
 union all select 'seed','dv_collect_private.tcg_languages',coalesce(jsonb_agg(to_jsonb(g) order by language_code collate "C"),'[]'::jsonb) from dv_collect_private.tcg_languages g

 union all select 'all_trigger',n.nspname||'.'||c.relname||'.'||t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)
 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','dv_market_private','dv_collect_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private')
 union all select 'catalog_constraint',n.nspname||'.'||c.relname||'.'||k.conname,jsonb_build_object('definition',pg_get_constraintdef(k.oid),'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred)
 from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','dv_market_private','dv_collect_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private') and k.contype<>'n'
 union all select 'catalog_index',n.nspname||'.'||c.relname,jsonb_build_object('definition',pg_get_indexdef(c.oid),'valid',i.indisvalid,'ready',i.indisready)
 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_index i on i.indexrelid=c.oid where n.nspname in ('public','dv_market_private','dv_collect_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private')
 union all select 'catalog_column',n.nspname||'.'||c.relname||'.'||a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text,'collation',co.collname)
 from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum left join pg_collation co on co.oid=a.attcollation
 where n.nspname in ('public','dv_market_private','dv_collect_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private') and a.attnum>0 and not a.attisdropped and c.relkind in ('r','p','v','m','S')
 union all select 'root_metadata',n.nspname||'.'||p.proname,jsonb_build_object('owner',r.rolname,'arguments',pg_get_function_arguments(p.oid),'result',pg_get_function_result(p.oid),'definer',p.prosecdef,'config',p.proconfig,'volatility',p.provolatile,'language',l.lanname,'acl',p.proacl::text)
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles r on r.oid=p.proowner join pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname in ('get_security_schema_readiness_v1','get_market_legal_schema_readiness_v1')
 union all select 'release_state','dv_collect_private.tcg_catalog_releases',coalesce(jsonb_agg(jsonb_build_object('game_key',r.game_key,'provider_key',r.provider_key,'provider_version',r.provider_version,'activation_contract',r.activation_contract,'scope_sha256',r.scope_sha256,'descriptor_sha256',r.descriptor_sha256,'schema_phase',r.schema_phase,'state',r.state,'source_review',r.source_terms_review_ref is not null,'attribution_review',r.attribution_review_ref is not null) order by game_key collate "C",provider_key collate "C",provider_version collate "C"),'[]'::jsonb) from dv_collect_private.tcg_catalog_releases r

 union all select 'm6_function','public.get_magic_on_demand_collection_beta_v1()',jsonb_build_object('definition',pg_get_functiondef(p.oid),'acl',p.proacl::text,'owner',r.rolname)
 from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='public.get_magic_on_demand_collection_beta_v1()'::regprocedure
 union all select 'm6_beta_contract','dv_collect_private.tcg_magic_on_demand_beta',coalesce(jsonb_agg(to_jsonb(b)-'enabled' order by game_key collate "C"),'[]'::jsonb) from dv_collect_private.tcg_magic_on_demand_beta b
